def portfolio_tracking_tool(portfolio_data):
    # Initialiser un dictionnaire pour stocker les données de suivi
    tracking_data = {}

    # Parcourir chaque investissement dans le portefeuille
    for investment in portfolio_data:
        # Calculer la performance de l'investissement
        performance = calculate_performance(investment)

        # Ajouter la performance à notre dictionnaire de suivi
        tracking_data[investment['name']] = {'performance': performance}

    return tracking_data

# Fonction hypothétique pour calculer la performance d'un investissement
# La logique réelle dépendra des données spécifiques et des métriques à suivre
def calculate_performance(investment):
    # Exemple de calcul simple
    return investment['current_value'] - investment['initial_value']

